#!/usr/bin/env python3
"""Summarize retained frozen results. Does not rerun or tune inference."""
import json,math,pathlib,statistics,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def dist(a,b):
 x,y=map(math.radians,[a[0],b[0]]);dlat=y-x;dlon=math.radians(b[1]-a[1]);h=math.sin(dlat/2)**2+math.cos(x)*math.cos(y)*math.sin(dlon/2)**2;return 12742000*math.asin(min(1,math.sqrt(h)))
def main():
 r=json.loads((ROOT/'docs/independent-validation.json').read_text());proto=json.loads((ROOT/'data/independent-validation/pathak-protocol.json').read_text());ref=proto['reference'];emb=proto['arbitrary_embedding'];summary={}
 for engine in ['baseline','revised']:
  single=[c for c in r['records'] if c['engine']==engine and 'ground_track_offset_error_m' in c];f=next(c for c in r['records'] if c['engine']==engine and c.get('kind')=='shared_site_all_five');a=json.loads((ROOT/f['result']).read_text())['fusion'];near=min(enumerate(a['heatmap']),key=lambda c:math.hypot(c[1]['lon']*emb['east_m_per_degree']-ref['reference_xy_m'][0],c[1]['lat']*emb['north_m_per_degree']-ref['reference_xy_m'][1])) if a['heatmap'] else None
  summary[engine]={'answers':len(single),'median_single_clip_distance_to_metadata_reference_m':statistics.median(c['distance_to_metadata_reference_m'] for c in single) if single else None,'median_ground_track_offset_error_m':statistics.median(c['ground_track_offset_error_m'] for c in single) if single else None,'all_five_fusion_distance_to_metadata_reference_m':f.get('distance_to_metadata_reference_m'),'nearest_tested_cell_distance_m':math.hypot(near[1]['lon']*emb['east_m_per_degree']-ref['reference_xy_m'][0],near[1]['lat']*emb['north_m_per_degree']-ref['reference_xy_m'][1]) if near else None,'nearest_tested_cell_rank':near[0]+1 if near else None,'fusion_joint_cells':len(a['heatmap'])}
 a=json.loads((ROOT/'validation-runs/improvement/colsto-final.json').read_text())['analysis'];c=a['candidates'][0];original={'distance_to_creator_map_reference_m':dist([c['lat'],c['lon']],[40.876728,-73.526434]),'estimate_lat_lon':[c['lat'],c['lon']],'matched_flights':[m['flight_id'] for m in c['matches']],'rms_hz':[m['rms_hz'] for m in c['matches']],'event_coverage':[m['event_coverage'] for m in c['matches']],'runner_up_score_gap':c['score']-a['candidates'][1]['score'],'search':a['search'],'result_sha256':hashlib.sha256((ROOT/'validation-runs/improvement/colsto-final.json').read_bytes()).hexdigest()}
 out={'summary':summary,'original_development_case':original,'frozen_source_and_protocol_checks_passed':True,'interpretation':'Ranking improved on five separate recordings, but top-ranked sites remain wrong by more than a kilometer. Nearest-cell rank is a diagnostic, not top-1 accuracy. No surveyed GPS accuracy or global aircraft-association accuracy is established.','after_evaluation_tuning':False};(ROOT/'docs/algorithm-improvement.json').write_text(json.dumps(out,indent=2)+'\n')
 lines=['# Algorithm diagnosis and separate-recording validation','','The revised method improves ranking on the original development recording and on five separate real recordings. It still does not provide reliable point locations. No parameters were retuned after the five-case evaluation.','','## Original recording used for development','',f"The prior high-recall 36-aircraft run placed its top candidate 4.45 km from the creator’s map reference. The frozen revised run places its top candidate **{original['distance_to_creator_map_reference_m']:.0f} m** from that reference, at {c['lat']:.6f}, {c['lon']:.6f}. It automatically associates the two separated passages with PC-12 N22NY and King Air N93CQ within the same 36-aircraft package. Source coverage remains 36 of 133 discovered regional aircraft.",'',f"The two retained supports have raw frequency RMS {original['rms_hz'][0]:.2f} and {original['rms_hz'][1]:.2f} Hz. They use {original['event_coverage'][0]:.0%} and {original['event_coverage'][1]:.0%} of their automatic path proposals. The next spatial candidate is only {original['runner_up_score_gap']:.2f} score units lower; neither the score nor this gap is calibrated confidence. The displayed creator coordinate is not surveyed microphone truth.",'','## Diagnosed causes and implemented changes','','1. **Greedy peak following lost the weak second pass.** Second-order dynamic programming now rewards continuity and penalizes slope changes. It searches overlapping time blocks and overlapping frequency bands; otherwise strong high-frequency clutter consumes every path slot. Event selection uses fractional frequency change in coherent mode, avoiding an arbitrary preference for high harmonics.','2. **Clock proposals added the wrong delay.** For uniform straight-line motion in still air, the steepest *received* Doppler drop occurs at emission-clock CPA, not CPA plus acoustic travel time. The old proposal was biased by roughly 18 s on the first pass. A test checks the clock proposal and the independently derived analytic frequency curve. Retarded-time propagation remains in the actual frequency model.','3. **The old null was too easy to beat.** Smooth clutter could outscore a stationary tone. Robust matching now compares against a fitted linear chirp and enforces the configured RMS scale on retained points. Fixed contiguous support alternatives tolerate contaminated ends, with an explicit window-search penalty and reported coverage. No hand-marked event windows are supplied.','4. **Unmatched-event penalties rewarded weak associations.** Robust mode uses a zero-evidence clutter alternative and prevents overlapping supports from being counted as independent passages.','5. **Joint search was expensive and pruned the wrong stage.** Coherent mode first tests individual anchors, keeps up to 16 distinct clocks per cell, then jointly evaluates all events. Anchor fits are counted, cancellation is checked, and their separate hard budget is 16 times `max_hypotheses`. The search remains heuristic and can miss modes.','', 'A narrow-band development improvement regressed when the analyzed band was widened. That regression motivated the frequency-band diversity change; it is not hidden as a successful broad-band result. Development attempts and final raw outputs are retained.','','## Evaluation protocol frozen before the new signals were run','','The implementation, exact inference configurations, data packages and evaluation script were SHA-256 frozen before testing. The earlier implementation is preserved under `validation-baseline/`. All five previously unused cases from the source constant-speed/height category were included: N4040_R12, N394FX_R20, N916KT_R22, N757AH_R41 and N413AK_R49. No case was removed because of its result. The four reserved AeroSonicDB files were also run; their event-proposal counts are not treated as detector accuracy.','', 'The five Pathak recordings are different aircraft passages from the [published dataset](https://zenodo.org/records/23424278). Their source tracks and finite recording-time intervals are supplied; this is **assisted association**, not a blind search over complete competing air traffic. No published frequency curve is supplied to inference.','', 'The common recorder reference was reconstructed without audio by intersecting three older cases’ published ground-track offsets with their KML tracks. Those constraints have residuals below 0.32 m, and the five new metadata offsets agree within 2.53 m. This is a strong internal metadata consistency check, **not a surveyed-GPS accuracy bound**. Source EGM96 heights are converted to relative local heights and embedded in an explicitly arbitrary local Cartesian frame; they are not relabeled ellipsoidal heights. The 10 km square prior is centered on a declared town coordinate, not the reconstructed receiver.','','## Results on the five separate recordings','','| Metric | Earlier method | Revised method |','|---|---:|---:|']
 for label,key in [('Single-clip median distance to reconstructed reference','median_single_clip_distance_to_metadata_reference_m'),('Single-clip median ground-track-offset error','median_ground_track_offset_error_m'),('All-five shared-site top-1 distance to reconstructed reference','all_five_fusion_distance_to_metadata_reference_m')]:lines.append(f"| {label} | {summary['baseline'][key]:.0f} m | {summary['revised'][key]:.0f} m |")
 lines.append(f"| Town-prior center baseline (no audio) | {r['origin_prior_baseline_distance_m']:.0f} m | {r['origin_prior_baseline_distance_m']:.0f} m |")
 lines.append(f"| Rank of nearest tested site cell ({summary['revised']['nearest_tested_cell_distance_m']:.0f} m from reference) | {summary['baseline']['nearest_tested_cell_rank']} | {summary['revised']['nearest_tested_cell_rank']} |")
 lines+=['','| Recording | Earlier point distance | Revised point distance | Earlier offset error | Revised offset error |','|---|---:|---:|---:|---:|']
 for case in proto['cases']:
  b=next(x for x in r['records'] if x['engine']=='baseline' and x.get('id')==case['id']);n=next(x for x in r['records'] if x['engine']=='revised' and x.get('id')==case['id']);lines.append(f"| {case['id']} | {b.get('distance_to_metadata_reference_m',math.nan):.0f} m | {n.get('distance_to_metadata_reference_m',math.nan):.0f} m | {b.get('ground_track_offset_error_m',math.nan):.0f} m | {n.get('ground_track_offset_error_m',math.nan):.0f} m |")
 lines+=['','All ten single-clip outputs remain `ambiguous`. A single nearly straight pass with an uncertain clock has along-track/time and mirror ambiguities. Cross-track offset is more identifiable than a unique map point. The revised point distance worsened for N757AH_R41, and N4040_R12 did not improve. The median individual point estimate is also worse than simply returning the declared town-prior center; only the shared-site fusion beats that baseline.','', 'Shared-site fusion sums profiled scores from **all five** recordings on the same coarse grid, with a separate clock for each recording and equal weights. Missing recordings are never silently dropped. All-five fusion remains 1.43 km wrong at rank one; the nearby cell ranks fourth, not first. The nearest-cell result is diagnostic evidence of improved ranking, not a substituted success metric. This small test does not establish broad generalization or calibrated geographic accuracy.','', 'The AeroSonicDB recordings have deliberately displaced public coordinates and no acquired historical tracks. Both engines found event proposals, and both withheld location without flight data. More proposals in revised mode do not prove better aircraft detection, so no recall/false-positive claim is made.','', '## Use and reproduce','', 'The web interface exposes **Coherent paths · research** and retains the legacy tracker. The synthetic demo explicitly selects legacy mode so its demonstration contract remains reproducible. Native coherent analysis uses:','','```bash','target/release/echo-locate analyze recording.wav --config data/coherent.config.json --package flights.package.json --output result.json','', '# Reproduce the old implementation from its preserved source.','cargo build --release --locked --manifest-path validation-baseline/Cargo.toml --target-dir target/baseline','python scripts/validate_independent.py','', '# Shared stationary site; same coarse grid and inference settings, separate clocks.','target/release/echo-locate fuse-site clip1.json clip2.json --output shared-site.json','```','','The evaluation checks frozen source/protocol hashes. Rebuilding on another toolchain can change binary hashes; every run records the actual binary fingerprint. Acquisition helpers restore the five CC BY 4.0 source cases, verifying the publisher’s full ZIP MD5. See `data/independent-validation/freeze.json`, `pathak-protocol.json`, `docs/independent-validation.json` and retained raw results.','','## Remaining causes of failure','','Residual path contamination, incorrect dominant-harmonic selection, source-frequency drift, trajectory/atmosphere errors and profiled-score calibration remain unresolved. The five-case results also expose weak ranking between mirror/along-track alternatives. Further tuning must use development material; these nine recordings are now exposed evaluation material and cannot be reused as a fresh test set.','', '![Original recording: observed spectral evidence and selected supports](algorithm-diagnosis.png)','', '![Shared-site scores on separate recordings](independent-site.png)']
 (ROOT/'docs/ALGORITHM_IMPROVEMENT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
